VALUES ('tpl_demorequest', 'demo-request', 'Demo request', 'Sales', 'Book a product demo and learn what to show before the call.', 'Half of a good demo is knowing what to skip. This asks what they want to see and which tools it has to sit alongside, then hands them straight to your booking link.', '["demo","sales","booking"]', 'MonitorPlay', 'choice', 2, 6, '{"schemaVersion":4,"title":"Demo request","description":"Book a product demo and learn what to show before the call.","blocks":[{"id":"blk_demorequ00","ref":"welcome","title":"Let''s get you a demo. Two minutes of questions so we don''t waste yours.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_demorequ01","ref":"contact","title":"Who should we be speaking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_demorequ02","ref":"company","title":"Which company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_demorequ03","ref":"decision_role","title":"What''s your role in the decision?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_decide","label":"I decide","image_key":null},{"id":"opt_i_recommend","label":"I recommend","image_key":null},{"id":"opt_i_m_researching","label":"I''m researching for someone else","image_key":null}],"allowOther":false},{"id":"blk_demorequ04","ref":"demo_focus","title":"What would you most like to see?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_basics_end","label":"The basics, end to end","image_key":null},{"id":"opt_integrations_with_our","label":"Integrations with our stack","image_key":null},{"id":"opt_security_and_complianc