at one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
