VALUES ('tpl_quoterequest', 'quote-request', 'Quote request', 'Sales', 'Scope a job well enough to price it without a call.', 'Most quote forms collect a name and a vague description, then cost you a discovery call anyway. This one asks about scope, timeline and budget range up front so the first reply can be a number.', '["quote","pricing","services"]', 'FileText', 'choice', 3, 7, '{"schemaVersion":4,"title":"Quote request","description":"Scope a job well enough to price it without a call.","blocks":[{"id":"blk_quotereq00","ref":"welcome","title":"Tell us what you need and we''ll come back with a price.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quotereq01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_quotereq02","ref":"email","title":"Where should we send the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_quotereq03","ref":"job_type","title":"What kind of work is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_build","label":"New build","image_key":null},{"id":"opt_redesign_of_something","label":"Redesign of something existing","image_key":null},{"id":"opt_ongoing_support","label":"Ongoing support","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_quotereq04","ref":"job_description","title":"Describe the job in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_quotereq05","ref":"budget","title":"What''s your budget range?","description":"A range is fine — it tells us what''s realistic.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_15k_50k","label":"$15k–$50k","image_key":null},{"id":"opt_50k","label":"$50k+","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather you suggest","image_key":null}],"allowOther":false},{"id":"blk_quotereq06","ref":"deadline","title":"When would you like it finished?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_quotereq07","ref":"attachments","title":"Anything to share? Briefs, drawings, screenshots.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10}],"endings":[{"id":"end_quotereq01","ref":"end_thanks","title":"On it 📝","bodyMd":"You''ll have a quote within two working days.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
