VALUES ('tpl_npssurvey', 'nps-survey', 'NPS survey', 'Product', 'Measure loyalty with the standard question and a real follow-up.', 'The score on its own tells you almost nothing you can act on. Asking why immediately after, while the number is still in mind, is what turns a metric into a list of things to fix.', '["nps","loyalty","survey"]', 'Gauge', 'scale', 2, 4, '{"schemaVersion":4,"title":"NPS survey","description":"Measure loyalty with the standard question and a real follow-up.","blocks":[{"id":"blk_npssurve00","ref":"welcome","title":"One quick question — it takes about twenty seconds.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_npssurve01","ref":"score","title":"How likely are you to recommend us to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_npssurve02","ref":"reason","title":"What''s the main reason for your score?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_npssurve03","ref":"improvement","title":"What''s the one thing we could change that would matter most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_npssurve04","ref":"follow_up_ok","title":"Would it be alright if someone followed up?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Sure","noLabel":"No thanks"}],"endings":[{"id":"end_npssurve01","ref":"end_thanks","title":"Thank you 💛","bodyMd":"Your answer shapes what we build next.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"set