INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_featurerequest', 'feature-request', 'Feature request', 'Product', 'Capture the problem behind the request, not just the request.', 'People ask for solutions; roadmaps need problems. Asking what they are trying to do and how they work around it today turns a wishlist into something a product team can actually prioritise.', '["roadmap","feedback","product"]', 'Lightbulb', 'scale', 2, 5, '{"schemaVersion":4,"title":"Feature request","description":"Capture the problem behind the request, not just the request.","blocks":[{"id":"blk_featurer00","ref":"welcome","title":"Got an idea? Tell us what you''re trying to do and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_featurer01","ref":"request","title":"In one line, what would you like to be able to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":200},{"id":"blk_featurer02","ref":"problem","title":"What are you trying to accomplish?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_featurer03","ref":"workaround","title":"How do you handle it today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_featurer04","ref":"importance","title":"How much would this change your day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_blocking","label":"It''s blocking me right now","image_key":null},{"id":"opt_it_would_save","label":"It would save me real time","image_key":null},{"id":"opt_it_would_be","label":"It would be nice to have","image_key":null}],"allowOther":false},{"id":"blk_featurer05","ref":"email","title":"Where can we reach you if we build it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false}],"endings":[{"id":"end_featurer01","ref":"end_thanks","title":"Logged 💡","bodyMd":"We read every one of these.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
