VALUES ('tpl_betasignup', 'beta-signup', 'Beta signup', 'Product', 'Recruit testers who will actually test.', 'A beta list full of people who never log in is worse than a short one. Asking about their setup and how much time they can give lets you invite in the order that gets you feedback fastest.', '["beta","research","recruiting"]', 'FlaskConical', 'scale', 2, 6, '{"schemaVersion":4,"title":"Beta signup","description":"Recruit testers who will actually test.","blocks":[{"id":"blk_betasign00","ref":"welcome","title":"Want early access? Tell us a little about how you''d use it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_betasign01","ref":"email","title":"Your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_betasign02","ref":"company","title":"Where do you work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_betasign03","ref":"platform","title":"Which platforms do you need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_web","label":"Web","image_key":null},{"id":"opt_ios","label":"iOS","image_key":null},{"id":"opt_android","label":"Android","image_key":null},{"id":"opt_desktop","label":"Desktop","image_key":null},{"id":"opt_api_only","label":"API only","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_betasign04","ref":"time_commitment","title":"How much time could you give in the first month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_hour_or","label":"An hour or two","image_key":null},{"id":"opt_a_few_hours","label":"A few hours","image_key":null},{"id":"opt_as_much_as","label":"As much as it takes","image_key":null}],"allowOther":false},{"id":"blk_betasign05","ref":"use_case","title":"What would you try first?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_betasign06","ref":"nda_consent","title":"Keeping it quiet","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I understand the beta is confidential and agree not to share screenshots or details publicly until launch."}],"endings":[{"id":"end_betasign01","ref":"end_thanks","title":"You''re on the list 🧪","bodyMd":"We''ll email you when your invite is ready.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
