VALUES ('tpl_cancellationsurvey', 'cancellation-survey', 'Cancellation survey', 'Product', 'Find out why people leave, without begging them to stay.', 'The exit is the most honest moment you get. Keep it short, ask the real reason as a choice you can count, and leave one open box for the thing your options didn''t anticipate.', '["churn","retention","feedback"]', 'DoorOpen', 'scale', 2, 3, '{"schemaVersion":4,"title":"Cancellation survey","description":"Find out why people leave, without begging them to stay.","blocks":[{"id":"blk_cancella00","ref":"welcome","title":"Sorry to see you go. Two questions, and then you''re done.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_cancella01","ref":"reason","title":"What''s the main reason you''re cancelling?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_expensive","label":"Too expensive","image_key":null},{"id":"opt_missing_a_feature","label":"Missing a feature I need","image_key":null},{"id":"opt_too_hard_to","label":"Too hard to use","image_key":null},{"id":"opt_found_a_better","label":"Found a better alternative","image_key":null},{"id":"opt_no_longer_need","label":"No longer need it","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_cancella02","ref":"detail","title":"Anything you''d like to add?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_cancella03","ref":"would_return","title":"Would you consider coming back if we fixed that?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Maybe","noLabel":"Unlikely"}],"endings":[{"id":"end_cancella01","ref":"end_thanks","title":"Thanks for the honesty 👋","bodyMd":"Your account stays active until the end of the period.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
