VALUES ('tpl_waitlist', 'waitlist', 'Launch waitlist', 'Marketing', 'Collect signups and learn who is waiting.', 'An email address alone gives you a number to announce and nothing to segment on. Two extra questions turn a waitlist into a launch plan: who they are, and what they came for.', '["waitlist","launch","growth"]', 'ListOrdered', 'content', 2, 5, '{"schemaVersion":4,"title":"Launch waitlist","description":"Collect signups and learn who is waiting.","blocks":[{"id":"blk_waitlist00","ref":"welcome","title":"Thanks for your interest! Get on the list and we''ll let you know the moment we''re live.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_waitlist01","ref":"email","title":"What''s your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_waitlist02","ref":"name","title":"And your name?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_waitlist03","ref":"role","title":"What best describes you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder","label":"Founder","image_key":null},{"id":"opt_developer","label":"Developer","image_key":null},{"id":"opt_designer","label":"Designer","image_key":null},{"id":"opt_marketer","label":"Marketer","image_key":null},{"id":"opt_just_curious","label":"Just curious","image_key":null}],"allowOther":false},{"id":"blk_waitlist04","ref":"hoping_for","title":"What are you hoping this will solve for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_waitlist05","ref":"referral","title":"How did you hear about us?","required":false,"visibility":null,"image_key":nu