ly","image_key":null},{"id":"opt_every_two_weeks","label":"Every two weeks","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null}],"allowOther":false},{"id":"blk_newslett05","ref":"consent","title":"Permission to email you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree to receive marketing emails and understand I can unsubscribe from any of them at any time."}],"endings":[{"id":"end_newslett01","ref":"end_thanks","title":"Subscribed ✉️","bodyMd":"Check your inbox to confirm.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBu