VALUES ('tpl_eventfeedback', 'event-feedback', 'Post-event feedback', 'Events', 'Rate the parts of an event separately, not as one blur.', 'A single “how was it?” averages a great speaker and a cold room into a seven. Rating the pieces separately in a grid tells you which one to fix, and takes a respondent no longer.', '["feedback","events","matrix"]', 'MessagesSquare', 'number', 2, 5, '{"schemaVersion":4,"title":"Post-event feedback","description":"Rate the parts of an event separately, not as one blur.","blocks":[{"id":"blk_eventfee00","ref":"welcome","title":"Thanks for coming! How did we do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventfee01","ref":"overall","title":"Overall, how was the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_eventfee02","ref":"aspects","title":"How would you rate each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_speakers","label":"Speakers"},{"id":"opt_row_venue","label":"Venue"},{"id":"opt_row_food_and","label":"Food and drink"},{"id":"opt_row_networking","label":"Networking"},{"id":"opt_row_organisation","label":"Organisation"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventfee03","ref":"highlight","title":"What was the highlight?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventfee04","ref":"improve","title":"What should we do differently next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"a