VALUES ('tpl_jobapplication', 'job-application', 'Job application', 'HR', 'Screen candidates with experience, links and a cover note.', 'Everything a first-pass review needs and nothing it doesn''t: who they are, what they''ve built, how much notice they have, and why this role. The CV upload is there, but the answers stand on their own.', '["hiring","recruiting","candidates"]', 'Briefcase', 'contact', 3, 8, '{"schemaVersion":4,"title":"Job application","description":"Screen candidates with experience, links and a cover note.","blocks":[{"id":"blk_jobappli00","ref":"welcome","title":"Glad you''re interested in joining us. Let''s start.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_jobappli01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_jobappli02","ref":"email","title":"Email address?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_jobappli03","ref":"role","title":"Which role are you applying for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_product","label":"Product","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null}],"allowOther":false},{"id":"blk_jobappli04","ref":"experience_years","title":"How many years of relevant experience?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","min":0,"max":60,"integerOnly":true},{"id":"blk_jobappli05","ref":"portfolio","title":"Portfolio, GitHub or LinkedIn","required":false,"visibility":null,"ima