VALUES ('tpl_bugreport', 'bug-report', 'Bug report', 'Support', 'Get reproducible reports instead of “it''s broken”.', 'Asks for the three things an engineer needs and a reporter always forgets: what they expected, what happened, and the exact steps between. Severity and environment come as fields you can filter on.', '["bugs","engineering","triage"]', 'Bug', 'advanced', 3, 8, '{"schemaVersion":4,"title":"Bug report","description":"Get reproducible reports instead of “it''s broken”.","blocks":[{"id":"blk_bugrepor00","ref":"welcome","title":"Sorry something''s broken. Let''s get the details down.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bugrepor01","ref":"summary","title":"In one line, what went wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":160},{"id":"blk_bugrepor02","ref":"steps","title":"What steps lead to it? Number them if you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_bugrepor03","ref":"expected","title":"What did you expect to happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":300},{"id":"blk_bugrepor04","ref":"actual","title":"What happened instead?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":300},{"id":"blk_bugrepor05","ref":"severity","title":"How badly is this affecting you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_can_t","label":"I can''t work at all","image_key":null},{"id":"opt_there_s_a","label":"There''s a workaround, but it''s painful","image_key":null},{"id":"opt_minor_annoyance","label":"Minor annoyance","image_key":null}],"allowOther":false},{"id":"blk_bugrepor06","ref":"environment","title":"Where did it happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_chrome","label":"Chrome","image_key":null},{"id":"opt_safari","label":"Safari","image_key":null},{"id":"opt_firefox","label":"Firefox","image_key":null},{"id":"opt_edge","label":"Edge","image_key":null},{"id":"opt_mobile_app","label":"Mobile app","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}],"allowOther":false},{"id":"blk_bugrepor07","ref":"screenshot","title":"A screenshot or recording, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":3,"maxSizeMB":25},{"id":"blk_bugrepor08","ref":"email","title":"Where should we reply?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false}],"endings":[{"id":"end_bugrepor01","ref":"end_thanks","title":"Reported 🐛","bodyMd":"Thanks — a real person reads every one of these.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
