VALUES ('tpl_refundrequest', 'refund-request', 'Refund request', 'Support', 'Handle refunds with the details a finance team needs.', 'Order reference, date, reason and preferred resolution — collected once so nobody has to email back asking for them. The reason list doubles as a running count of why people ask.', '["refund","billing","ecommerce"]', 'ReceiptText', 'advanced', 2, 6, '{"schemaVersion":4,"title":"Refund request","description":"Handle refunds with the details a finance team needs.","blocks":[{"id":"blk_refundre00","ref":"welcome","title":"Let''s sort this out. A few details about the order.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_refundre01","ref":"email","title":"The email used for the order?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_refundre02","ref":"order_reference","title":"Order or invoice number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":60},{"id":"blk_refundre03","ref":"order_date","title":"Roughly when did you order?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_refundre04","ref":"reason","title":"Why are you requesting a refund?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_not_what_i","label":"Not what I expected","image_key":null},{"id":"opt_arrived_damaged_or","label":"Arrived damaged or faulty","image_key":null},{"id":"opt_never_arrived","label":"Never arrived","image_key":null},{"id":"opt_charged_twice","label":"Charged twice","image_key":null},{"id":"opt_changed_my_mind","label":"Changed my mind","image_key":null}],"allowOther":false},{"id":"blk_refundre05","ref":"resolution","title":"What would you like us to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_refund_to_my","label":"Refund to my original payment method","image_key":null},{"id":"opt_store_credit","label":"Store credit","image_key":null},{"id":"opt_replacement","label":"Replacement","image_key":null}],"allowOther":false},{"id":"blk_refundre06","ref":"detail","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_refundre01","ref":"end_thanks","title":"Request received 💳","bodyMd":"Refunds are usually processed within five working days.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
