maxLength":800,"aiQualityCheck":false},{"id":"blk_courseen06","ref":"schedule","title":"When can you study?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weekday_mornings","label":"Weekday mornings","image_key":null},{"id":"opt_weekday_evenings","label":"Weekday evenings","image_key":null},{"id":"opt_weekends","label":"Weekends","image_key":null},{"id":"opt_any_time","label":"Any time","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_courseen07","ref":"accessibility","title":"Anything we should know to support you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_courseen01","ref":"end_thanks","title":"You''re enrolled 🎓","bodyMd":"Your welcome pack is on its way.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that