VALUES ('tpl_studentfeedback', 'student-feedback', 'Student feedback', 'Education', 'End-of-course feedback that separates teaching from material.', 'A course can have excellent material and a rushed delivery, or the reverse. Rating them apart — and asking about pace separately again — is what makes the answers actionable rather than flattering.', '["teaching","feedback","course"]', 'BookOpen', 'text', 2, 6, '{"schemaVersion":4,"title":"Student feedback","description":"End-of-course feedback that separates teaching from material.","blocks":[{"id":"blk_studentf00","ref":"welcome","title":"You made it to the end! How was it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_studentf01","ref":"overall","title":"Overall, how would you rate the course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_studentf02","ref":"aspects","title":"How would you rate each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_course_material","label":"Course material"},{"id":"opt_row_teaching","label":"Teaching"},{"id":"opt_row_exercises","label":"Exercises"},{"id":"opt_row_pace","label":"Pace"},{"id":"opt_row_support","label":"Support"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_studentf03","ref":"pace","title":"How was the pace?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_slow","label":"Too slow","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_fast","label":"Too fast","image_key":null}],"allowOther":false},{"id":"blk_studentf04","ref":"most_useful","title":"What was most useful?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentf05","ref":"least_useful","title":"What would you cut or change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentf06","ref":"recommend","title":"How likely are you to recommend this course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"}],"endings":[{"id":"end_studentf01","ref":"end_thanks","title":"Thank you 📚","bodyMd":"Every cohort improves because of answers like these.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"esca