VALUES ('tpl_quiz', 'quiz', 'Knowledge quiz', 'Education', 'A scored quiz you can swap the questions out of.', 'Three worked example questions with scores already attached to the options, so the scoring wiring is done and you only replace the wording. Use it for onboarding checks, course tests or lead-scoring quizzes.', '["quiz","scoring","assessment"]', 'ListChecks', 'text', 2, 5, '{"schemaVersion":4,"title":"Knowledge quiz","description":"A scored quiz you can swap the questions out of.","blocks":[{"id":"blk_quiz00","ref":"welcome","title":"Five questions. No pressure — you''ll get your score at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quiz01","ref":"name","title":"What should we call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_quiz02","ref":"q1","title":"Which of these is a primary colour?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_green","label":"Green","image_key":null,"score":0},{"id":"opt_blue","label":"Blue","image_key":null,"score":1},{"id":"opt_orange","label":"Orange","image_key":null,"score":0},{"id":"opt_purple","label":"Purple","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quiz03","ref":"q2","title":"Which of these are mammals? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_dolphin","label":"Dolphin","image_key":null,"score":1},{"id":"opt_shark","label":"Shark","image_key":null,"score":0},{"id":"opt_bat","label":"Bat","image_key":null,"score":1},{"id":"opt_penguin","label":"Penguin","image_key":null,"score":0}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_quiz04","ref":"q3","title":"Is the Pacific the largest ocean on Earth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_quiz05","ref":"confidence","title":"How confident are you in your answers?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Guessing","labelHigh":"Certain"}],"endings":[{"id":"end_quiz01","ref":"end_thanks","title":"Nicely done ✅","bodyMd":"Swap in your own questions — the scores are already wired up.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radi