VALUES ('tpl_clientintake', 'client-intake', 'New client intake', 'Services', 'Everything you need before the first client session.', 'Replaces the intake PDF nobody fills in. Contact details, what they''re here for, how they found you, and a signed agreement — collected once, before the first meeting rather than during it.', '["intake","clients","agency"]', 'ClipboardList', 'text', 3, 7, '{"schemaVersion":4,"title":"New client intake","description":"Everything you need before the first client session.","blocks":[{"id":"blk_clientin00","ref":"welcome","title":"Welcome! A few questions so we''re ready for our first session.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientin01","ref":"contact","title":"Your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clientin02","ref":"address","title":"Your address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"]},{"id":"blk_clientin03","ref":"service","title":"What are you here for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_initial_consultation","label":"An initial consultation","image_key":null},{"id":"opt_an_ongoing_engagement","label":"An ongoing engagement","image_key":null},{"id":"opt_a_one_off","label":"A one-off project","image_key":null},{"id":"opt_a_second_opinion","label":"A second opinion","image_key":null}],"allowOther":false},{"id":"blk_clientin04","ref":"background","title":"Tell us the background in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_clientin05","ref":"goals","title":