VALUES ('tpl_appointmentbooking', 'appointment-booking', 'Appointment booking', 'Services', 'Take a booking with a date, a time and a reason.', 'A date block with time turned on, so the answer is an actual appointment rather than a day. Asking the reason and whether they''ve been before is what lets you allocate the right slot length.', '["booking","appointments","scheduling"]', 'CalendarClock', 'text', 3, 7, '{"schemaVersion":4,"title":"Appointment booking","description":"Take a booking with a date, a time and a reason.","blocks":[{"id":"blk_appointm00","ref":"welcome","title":"Let''s find you a time.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_appointm01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_appointm02","ref":"phone","title":"Best number to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone"},{"id":"blk_appointm03","ref":"email","title":"Email?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_appointm04","ref":"reason","title":"What''s the appointment for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_first_consultation","label":"First consultation","image_key":null},{"id":"opt_follow_up","label":"Follow-up","image_key":null},{"id":"opt_routine_check","label":"Routine check","image_key":null},{"id":"opt_something_urgent","label":"Something urgent","image_key":null}],"allowOther":false},{"id":"blk_appointm05","ref":"preferred_slot","title":"When suits you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"17:30"},{"id":"blk_appointm06","ref":"first_visit","title":"Is this your first visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_appointm07","ref":"notes","title":"Anything we should know beforehand?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_appointm01","ref":"end_thanks","title":"Booked 🗓️","bodyMd":"We''ll confirm by text shortly.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
