VALUES ('tpl_volunteersignup', 'volunteer-signup', 'Volunteer signup', 'Community', 'Match volunteers to shifts they can actually make.', 'Availability and skills asked as structured choices, so a coordinator can fill a rota by filtering rather than by reading. The emergency contact is there because most volunteer schemes need one.', '["volunteers","nonprofit","rota"]', 'HandHeart', 'content', 3, 7, '{"schemaVersion":4,"title":"Volunteer signup","description":"Match volunteers to shifts they can actually make.","blocks":[{"id":"blk_voluntee00","ref":"welcome","title":"Thanks for offering to help! Tell us when you''re free and what you''d like to do.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_voluntee01","ref":"name","title":"Your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_voluntee02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_voluntee03","ref":"phone","title":"Mobile number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone"},{"id":"blk_voluntee04","ref":"availability","title":"When are you available?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weekday_mornings","label":"Weekday mornings","image_key":null},{"id":"opt_weekday_afternoons","label":"Weekday afternoons","image_key":null},{"id":"opt_weekday_evenings","label":"Weekday evenings","image_key":null},{"id":"opt_saturdays","label":"Saturdays","image_key":null},{"id":"opt_sundays","label":"Sundays","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_voluntee05","ref":"interests","title":"What would you like to help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_events_and_stewarding","label":"Events and stewarding","image_key":null},{"id":"opt_fundraising","label":"Fundraising","image_key":null},{"id":"opt_admin_and_data","label":"Admin and data","image_key":null},{"id":"opt_driving_and_deliveries","label":"Driving and deliveries","image_key":null},{"id":"opt_working_with_people","label":"Working with people directly","image_key":null},{"id":"opt_whatever_s_needed","label":"Whatever''s needed","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_voluntee06","ref":"experience","title":"Any relevant experience or skills?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_voluntee07","ref":"emergency_contact","title":"Emergency contact — name and number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500}],"endings":[{"id":"end_voluntee01","ref":"end_thanks","title":"Welcome to the team 💚","bodyMd":"A coordinator will be in touch with the rota.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
