VALUES ('tpl_membershipapplication', 'membership-application', 'Membership application', 'Community', 'Take applications with the tier and the terms in one pass.', 'Tier chosen, code of conduct signed, and a line on why they want to join — everything a membership secretary would otherwise chase over three emails.', '["membership","club","community"]', 'BadgeCheck', 'content', 3, 7, '{"schemaVersion":4,"title":"Membership application","description":"Take applications with the tier and the terms in one pass.","blocks":[{"id":"blk_membersh00","ref":"welcome","title":"Glad you want to join us. A few questions and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_membersh01","ref":"name","title":"Your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","minLength":0,"maxLength":500},{"id":"blk_membersh02","ref":"email","title":"Email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","businessOnly":false},{"id":"blk_membersh03","ref":"date_of_birth","title":"Date of birth","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"DD/MM/YYYY","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_membersh04","ref":"tier","title":"Which membership?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_standard","label":"Standard","description":"Full access, billed yearly","image_key":null},{"id":"opt_concession","label":"Concession","description":"Students, over-65s and unwaged","image_key":null},{"id":"opt_household","label":"Household","description":"Up to four people at one address","image_key":null},{"id":"opt_life_member","label":"Life member","image_key":null}],"allowOther":false},{"id":"blk_membersh05","ref":"motivation","title":"Why would you like to join?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_membersh06","ref":"how_heard","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_member","label":"A member","image_key":null},{"id":"opt_an_event","label":"An event","image_key":null},{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}],"allowOther":false},{"id":"blk_membersh07","ref":"code_of_conduct","title":"Code of conduct","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read the code of conduct and agree to abide by it as a member."}],"endings":[{"id":"end_membersh01","ref":"end_thanks","title":"Application in 🎟️","bodyMd":"The committee reviews applications monthly.","imageUrl":null,"redirectDelaySec":5,"showSummary":false}],"endingRules":[],"logic":[],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":false},"closeRules":{"closedMessageMd":"This form is no longer accepting responses."},"requireAuth":{"enabled":false,"methods":["google"],"message":"Before we start, could you verify who you are? It only takes a moment.","onePerIdentity":false},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"duplicates":{"strategy":"none"},"onComplete":{"requireSubmit":true,"delaySec":5,"notificationEmails":[],"autoReplyEmail":{"enabled":false,"subject":"Thanks for your response","bodyMd":""}},"meta":{"ogImageKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"ai","tone":"friendly","language":"en","rephraseQuestions":true,"knowledge":[],"guardrails":{"answerOffTopic":true,"maxTurns":60,"refusalMessage":"I''m not sure about that one — but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"sessionTokenBudget":12000,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#faf7f2","surface":"#ffffff","text":"#1c1917","accent":"#f97316","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#f97316","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
